import{_ as e,o as t,c as l,a2 as i}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"4.1 设置触发条件与主动建议","description":"发现值得处理的事，并解释为什么现在重要。","frontmatter":{"title":"4.1 设置触发条件与主动建议","description":"发现值得处理的事，并解释为什么现在重要。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-4/4-1.md","filePath":"delivery/stage-4/4-1.md","lastUpdated":1794017073000}'),r={name:"delivery/stage-4/4-1.md"};function o(n,a,s,d,_,h){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="_4-1-设置触发条件与主动建议" tabindex="-1">4.1 设置触发条件与主动建议 <a class="header-anchor" href="#_4-1-设置触发条件与主动建议" aria-label="Permalink to &quot;4.1 设置触发条件与主动建议&quot;">​</a></h1><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li><strong>已实现：</strong> 六类触发器：截止窗口、任务失败或可恢复、外部动作结果不确定、审批等待超时、来源出现新条目、队列积压或长任务；建议包含来源、原因、动作、影响、成本、风险和优先级，并按事件去重。</li><li><strong>仍未完成：</strong> 邮件和日历触发器只有禁用占位；主动模式只生成建议，不直接执行高风险动作。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让 Hearth 能从用户授权的信息来源中发现值得处理的事情，并解释为什么现在需要用户关注。这个阶段只提出建议，不自动执行高风险动作。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>从邮件、日历、文件和已有关注事项中产生候选事件。</li><li>对重复事件去重，设置冷却时间，避免同一件事反复提醒。</li><li>每条建议都说明来源、为什么现在重要、建议做什么、预计影响和是否需要审批。</li><li>用户可以选择接受、忽略、稍后提醒或转成普通任务。</li><li>先在不产生真实影响的情况下试运行，观察建议是否准确、是否过多。</li><li>没有明确授权、预算或停止方式时，不开放主动执行。</li></ol>',7)])])}const p=e(r,[["render",o]]);export{u as __pageData,p as default};
